    rootJs: "async function relocateComponent(params) {\n    if (![params.x, params.y].every(Number.isFinite))\n        throw new Error('移动坐标无效');\n    const rows = (await eda.pcb_PrimitiveComponent.getAll()).filter((c) => stateValue(c, 'Designator') === params.designator);\n    if (rows.length !== 1 || stateValue(rows[0], 'PrimitiveLock'))\n        throw new Error('元件不存在、不唯一或已锁定');\n    const { pads } = await getPads({ designator: params.designator });\n    const nets = [...new Set(pads.map((p) => p.net).filter(Boolean))];\n    const deletedTracks = [];\n    for (const net of nets) {\n        const { tracks } = await getTracks({ net });\n        for (const t of tracks) {\n            const touches = pads.some((p) => p.net === net && (p.layer === 12 || p.layer === t.layer)\n                && [[t.startX, t.startY], [t.endX, t.endY]].some(([x, y]) => p.bbox\n                    ? x >= p.bbox.minX && x <= p.bbox.maxX && y >= p.bbox.minY && y <= p.bbox.maxY\n                    : Math.hypot(x - p.x, y - p.y) < 0.001));\n            if (touches)\n                deletedTracks.push(t.primitiveId);\n        }\n    }\n    if (deletedTracks.length && !await eda.pcb_PrimitiveLine.delete(deletedTracks))\n        throw new Error('断开走线失败，元件未移动');\n    const rotation = params.rotation ?? stateValue(rows[0], 'Rotation', 0);\n    if (!await eda.pcb_PrimitiveComponent.modify(stateValue(rows[0], 'PrimitiveId'), { x: params.x, y: params.y, rotation }))\n        throw new Error('元件移动失败');\n    return { moved: params.designator, x: params.x, y: params.y, rotation, deletedTracks, deletedTrackCount: deletedTracks.length, netsToReroute: nets };\n}",
